  let px = 0.36, py = -0.4, pz = -0.62, rx = -0.5, ry = -0.15, rz = 0.08;
  if (cls === 'spear') { px = 0.3; py = -0.34; pz = -0.35; rx = -1.42; ry = 0.06; rz = 0; }
