  if (cls === 'rod') { px = 0.34; py = -0.42; pz = -0.5; rx = -0.95; }
  if (cls === 'hands') { px = 0.3; py = -0.34; pz = -0.62; rx = -0.35; ry = 0.25; rz = 0.15; }
  if (cls === 'torch') { px = 0.42; py = -0.55; pz = -0.85; rx = -0.15; ry = -0.1; rz = 0.12; }
