    if (Math.random() < 0.85) { const n = f.rich ? 2 : 1; give('rawfish', n); G.stats.fish += n; addXP(6); sfx('splash'); puff(f.x, f.y0 + 0.2, f.z, 0xbfe6ff, 8, { size: 0.15 }); if (G.stats.fish >= 5) badge('angler'); }
